INSERT INTO [etg].[contracts_db_operations] ([key_guid], [ref_package_guid], [pub_op], [pub_query_mssql], [pub_query_postgres], [pub_query_mysql], [pub_bootstrap_element], [pub_notes], [ref_input_model_guid], [ref_output_model_guid]) VALUES ('FFE1A2B9-32EA-5754-9617-FFF3CB587E37', 'F1954052-001D-5818-90DC-1953ADA7ABA1', 'db:workflow:queue:claim:1', 'SET NOCOUNT ON; DECLARE @claimed TABLE ([key_guid] UNIQUEIDENTIFIER NOT NULL, [ref_definition_guid] UNIQUEIDENTIFIER NOT NULL, [pub_batch_number] BIGINT NOT NULL, [pub_steps] NVARCHAR(MAX) NOT NULL, [pub_can_retry] BIT NOT NULL, [pub_max_attempts] TINYINT NOT NULL, [pub_attempts] TINYINT NOT NULL); WITH [next] AS (SELECT TOP (1) [swq].[key_guid] FROM [dbo].[system_workflow_queue] AS [swq] WITH (UPDLOCK, READPAST, ROWLOCK) WHERE [swq].[ref_status_enum_guid] = ? ORDER BY [swq].[priv_created_on]) UPDATE [swq] SET [swq].[ref_status_enum_guid] = ?, [swq].[pub_attempts] = [swq].[pub_attempts] + 1, [swq].[pub_started_on] = SYSDATETIMEOFFSET(), [swq].[priv_modified_on] = SYSDATETIMEOFFSET() OUTPUT [inserted].[key_guid], [inserted].[ref_definition_guid], [inserted].[pub_batch_number], [inserted].[pub_steps], [inserted].[pub_can_retry], [inserted].[pub_max_attempts], [inserted].[pub_attempts] INTO @claimed FROM [dbo].[system_workflow_queue] AS [swq] JOIN [next] ON [next].[key_guid] = [swq].[key_guid]; SELECT [c].[key_guid], [c].[ref_definition_guid], [c].[pub_batch_number], [c].[pub_steps], [c].[pub_can_retry], [c].[pub_max_attempts], [c].[pub_attempts] FROM @claimed AS [c] FOR JSON PATH, WITHOUT_ARRAY_WRAPPER', NULL, NULL, 0, 'The atomic claim: the oldest PENDING row becomes RUNNING, its attempt counted and started_on stamped, in one statement; returns the claim shape, or nothing when the queue is empty.', '9067214C-8973-5FEF-A668-F4586B504304', '80D2901A-88E2-5B2B-98BB-3867AC2EA2C4');
IF NOT EXISTS (SELECT 1 FROM [etg].[contracts_db_operations] WHERE [key_guid] = 'C384EA90-E758-527F-B76F-668562A41FD3')
